// ========== 辅助函数(随机抽字符串) ==========
function randomPick(arr) {
    return arr[Math.floor(Math.random() * arr.length)]
}
// ========== 辅助函数(检测范围内空方块) ==========
function checkAreaWithAABBIsEmptyBlockWithoutCore(level, aabb, corePos) {
    const { minX, minY, minZ, maxX, maxY, maxZ } = aabb;
    const coreX = corePos.x;
    const coreY = corePos.y;
    const coreZ = corePos.z;

    for (let x = minX; x <= maxX; x++) {
        for (let y = minY; y <= maxY; y++) {
            for (let z = minZ; z <= maxZ; z++) {
                if (x == coreX && y == coreY && z == coreZ) {
                    continue;
                }
                if (!level.isEmptyBlock([x, y, z])) {
                    return false;
                }
            }
        }
    }
    return true;
}
// ========== 辅助函数(检测范围内是否全是方块) ==========
function isAABBSolid(level, aabb) {
    const { minX, minY, minZ, maxX, maxY, maxZ } = aabb;

    for (let x = minX; x <= maxX; x++) {
        for (let y = minY; y <= maxY; y++) {
            for (let z = minZ; z <= maxZ; z++) {

                if (level.isEmptyBlock([x, y, z])) {
                    return false;
                }
            }
        }
    }
    return true;
}

// ========== 辅助函数(动态结构) ==========
const $MinecartContraptionItem = Java.loadClass("com.simibubi.create.content.contraptions.mounted.MinecartContraptionItem")
const $OrientedContraptionEntity = Java.loadClass("com.simibubi.create.content.contraptions.OrientedContraptionEntity")
function ContraptionUpPlace(pos, level, itemStack, TARGET_YAW) {
    const minecart = level.createEntity("minecraft:minecart")
    minecart.setPos(pos.x + 0.5, pos.y - 7, pos.z + 0.5)
    minecart.spawn()

    $MinecartContraptionItem.addContraptionToMinecart(level, itemStack, minecart, null)

    let contraptionEntity = null
    let gotContraption = false

    // ===== 上升参数 =====
    let speed = 0.25
    let counter = 1
    const maxHeight = 6

    level.server.scheduleRepeatingInTicks(1, tickEvent => {
        try {
            // ---- 获取实体（如果尚未获取） ----
            if (!gotContraption) {
                if (minecart.getPassengers().length > 0) {
                    let passenger = minecart.getPassengers()[0]
                    if (passenger instanceof $OrientedContraptionEntity) {
                        contraptionEntity = passenger
                        gotContraption = true
                        contraptionEntity.yaw = TARGET_YAW
                        contraptionEntity.prevYaw = TARGET_YAW
                        contraptionEntity.targetYaw = TARGET_YAW
                        contraptionEntity.pitch = 0
                        contraptionEntity.prevPitch = 0
                    }
                }
                if (!gotContraption) {
                    return // 等待下一 tick
                }
            }

            // ---- 到达高度后清除 ----
            if (counter * speed > maxHeight) {
                level.server.scheduleInTicks(10, () => {
                    minecart.discard()
                })
                tickEvent.clear()
                return
            }

            // ---- 上升位移 ----
            let targetX = pos.x + 0.5
            let targetZ = pos.z + 0.5
            let targetY = pos.y - 7 + speed * counter
            minecart.setPos(targetX, targetY, targetZ)
            minecart.setDeltaMovement(new Vec3d(0, 0, 0))

            // ---- 锁定角度 ----
            if (contraptionEntity.isAlive()) {
                contraptionEntity.yaw = TARGET_YAW
                contraptionEntity.prevYaw = TARGET_YAW
                contraptionEntity.targetYaw = TARGET_YAW
                contraptionEntity.pitch = 0
                contraptionEntity.prevPitch = 0
            } else {
                tickEvent.clear()
                return
            }

            counter++
        } catch (e) {
            console.error("[动态结构] 错误: " + e)
            tickEvent.clear()
        }
    })
}
// ========== 辅助函数：在 AABB 区域生成粒子 ==========
const $BlockParticleOption = Java.loadClass('net.minecraft.core.particles.BlockParticleOption')
const $ParticleTypes = Java.loadClass('net.minecraft.core.particles.ParticleTypes')
/**
 * 在 AABB 区域内的每个非空气方块表面，生成挖掘/破碎粒子效果
 * 
 * @param {Internal.Level} level
 * @param {Internal.AABB} aabb
 */
function spawnBlockBreakParticlesInAABB(level, aabb) {
    const { minX, minY, minZ, maxX, maxY, maxZ } = aabb;
    const startX = Math.floor(Math.min(minX, maxX));
    const endX   = Math.floor(Math.max(minX, maxX));
    const startY = Math.floor(Math.min(minY, maxY));
    const endY   = Math.floor(Math.max(minY, maxY));
    const startZ = Math.floor(Math.min(minZ, maxZ));
    const endZ   = Math.floor(Math.max(minZ, maxZ));

    // 遍历 AABB 区域
    for (let x = startX; x <= endX; x++) {
        for (let y = startY; y <= endY; y++) {
            for (let z = startZ; z <= endZ; z++) {
                let blockState = level.getBlockState(new BlockPos(x, y, z));
                if (blockState.isAir()) continue;

                let blockparticle = new $BlockParticleOption($ParticleTypes.BLOCK, blockState)
                level.spawnParticles(blockparticle, true, x, y + 1, z, 0.3, 0.5, 0.3, 10, 0.05)
            }
        }
    }
}

