MBDMachineEvents.onStructureInvalid('materialfactory:blender_controller', e => {
    let { machine } = e.getEvent()
    let { level } = machine
    let facing = machine.frontFacing.get()
    let middleblockpos = level.getBlock(machine.pos).offset(facing.opposite, 3).pos
    let behindblockpos = level.getBlock(machine.pos).offset(facing.opposite, 6).pos
    let topblockpos = level.getBlock(machine.pos).offset(facing.opposite, 5).offset(Direction.UP, 6).pos
    const aabb1 = AABB.of(middleblockpos.x - 3, middleblockpos.y, middleblockpos.z - 3, middleblockpos.x + 3, middleblockpos.y, middleblockpos.z + 3)
    const aabb2 = AABB.of(middleblockpos.x - 2, middleblockpos.y + 1, middleblockpos.z - 2, middleblockpos.x + 2, middleblockpos.y + 4, middleblockpos.z + 2)
    const aabb3 = AABB.of(middleblockpos.x - 3, middleblockpos.y + 5, middleblockpos.z - 3, middleblockpos.x + 3, middleblockpos.y + 5, middleblockpos.z + 3)
    const aabb4 = AABB.of(middleblockpos.x - 1, middleblockpos.y + 6, middleblockpos.z - 1, middleblockpos.x + 1, middleblockpos.y + 6, middleblockpos.z + 1)
    const aabb5 = AABB.of(behindblockpos.x, behindblockpos.y + 1, behindblockpos.z, behindblockpos.x, behindblockpos.y + 6, behindblockpos.z)
    level.destroyBlock(topblockpos, false)
    destroyAABB(level, aabb1, true)
    destroyAABB(level, aabb2, false)
    destroyAABB(level, aabb3, false)
    destroyAABB(level, aabb4, false)
    destroyAABB(level, aabb5, false)
})
/**
 * 破坏AABB区域的所有方块
 * @param {Internal.Level} level
 * @param {Internal.AABB} aabb 
 * @param {boolean} mode 
 */
function destroyAABB(level, aabb, mode) {
    for (let x = aabb.minX; x <= aabb.maxX; x++) {
        for (let y = aabb.minY; y <= aabb.maxY; y++) {
            for (let z = aabb.minZ; z <= aabb.maxZ; z++) {
                let pos = new BlockPos(x, y, z)
                level.destroyBlock(pos, mode)
            }
        }
    }
}